1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"fmt"
17		"sort"
18	)
19	
20	// SnapshotFormatVersion is the only on-disk snapshot format understood.
21	const SnapshotFormatVersion = 1
22	
23	// SnapshotFile is the on-disk representation of one frozen lineage graph.
24	//
25	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
26	// verified against Graph on every read; Graph carries the complete graph.
27	type SnapshotFile struct {
28		FormatVersion int       `json:"formatVersion"`
29		ContentID     string    `json:"contentId"`
30		Graph         GraphFile `json:"graph"`
31	}
32	
33	// RootSourceChange reports that one dataset present in BOTH versions reaches a
34	// different set of root sources. OldRoots and NewRoots are sorted by name and
35	// never nil, so empty root sets encode as [] rather than null.
36	type RootSourceChange struct {
37		Dataset  string   `json:"dataset"`
38		OldRoots []string `json:"oldRoots"`
39		NewRoots []string `json:"newRoots"`
40	}
41	
42	// CompareReport is the deterministic, read-only diff of two snapshots read in
43	// the fixed direction old -> new.
44	//
45	// NewDatasets and RemovedDatasets list nodes present on only one side.
46	// ChangedDatasets lists datasets present on both sides whose direct upstream
47	// set actually changed. AddedRelations and RemovedRelations list every
48	// directed edge present on only one side, including edges that vanish because
49	// one endpoint node was removed. RootSourceChanges covers only datasets common
50	// to both versions whose reachable root set differs; added or removed datasets
51	// never appear there.
52	type CompareReport struct {
53		NewDatasets       []string           `json:"newDatasets"`
54		RemovedDatasets   []string           `json:"removedDatasets"`
55		ChangedDatasets   []string           `json:"changedDatasets"`
56		AddedRelations    []Relation         `json:"addedRelations"`
57		RemovedRelations  []Relation         `json:"removedRelations"`
58		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
59	}
60	
61	// contentIDPrefix names the hash algorithm used for content addressing.
62	const contentIDPrefix = "sha256:"
63	
64	// canonicalGraph serializes the graph's semantics deterministically: datasets
65	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
66	// JSON with no insignificant whitespace. Two semantically equal graphs always
67	// produce identical bytes.
68	func canonicalGraph(adj adjacency) ([]byte, error) {
69		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
70		return json.Marshal(gf)
71	}
72	
73	// computeContentID returns the content identifier of the graph bytes:
74	// "sha256:" followed by the lowercase hex SHA-256 digest.
75	func computeContentID(canonical []byte) string {
76		sum := sha256.Sum256(canonical)
77		return contentIDPrefix + hex.EncodeToString(sum[:])
78	}
79	
80	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
81	// version 1 and the matching content identifier. It does not mutate graph. The
82	// returned document and its serialized bytes depend only on graph semantics.
83	//
84	// A dataset name or direct upstream reference that is not valid UTF-8 rejects
85	// the build with no snapshot and no content identifier: such bytes could not be
86	// serialized without silently rewriting the name, so the frozen document would
87	// not be a faithful, readable copy of the graph.
88	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
89		// One read of the existing graph settles its legality and yields the
90		// canonical relations the snapshot freezes — the same shared judgment
91		// ValidateGraph, preview, apply, and graph export make.
92		adj, err := validatedGraphAdjacency(graph)
93		if err != nil {
94			return nil, err
95		}
96		canonical, err := canonicalGraph(adj)
97		if err != nil {
98			return nil, err
99		}
100		return &SnapshotFile{
101			FormatVersion: SnapshotFormatVersion,
102			ContentID:     computeContentID(canonical),
103			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
104		}, nil
105	}
106	
107	// MarshalSnapshot serializes a snapshot the same way for every save: indented
108	// JSON keyed by struct field order, terminated by a single newline.
109	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
110		var buf bytes.Buffer
111		enc := json.NewEncoder(&buf)
112		enc.SetIndent("", "  ")
113		enc.SetEscapeHTML(false)
114		if err := enc.Encode(snap); err != nil {
115			return nil, err
116		}
117		return buf.Bytes(), nil
118	}
119	
120	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
121	// can distinguish "field absent" from "field present with a zero value"
122	// (e.g. a missing formatVersion must be rejected rather than read as 0).
123	type rawSnapshot struct {
124		FormatVersion json.RawMessage `json:"formatVersion"`
125		ContentID     json.RawMessage `json:"contentId"`
126		Graph         json.RawMessage `json:"graph"`
127	}
128	
129	// isJSONNull reports whether a raw JSON value is the literal null.
130	func isJSONNull(raw json.RawMessage) bool {
131		return string(bytes.TrimSpace(raw)) == "null"
132	}
133	
134	// ParseSnapshot parses and strictly validates one snapshot document: required
135	// fields must be present and well-typed, no known field may be declared twice
136	// within the same object (even with identical values, a null first, or a
137	// spelling equivalent under Unicode case folding or JSON escaping), the
138	// format version must be supported, the embedded graph must be structurally
139	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
140	// and the content identifier must correspond exactly to the graph. A
141	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
142	// can never be trusted as a version.
143	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
144		if err := checkDuplicateFields(data); err != nil {
145			return nil, err
146		}
147		var raw rawSnapshot
148		if err := json.Unmarshal(data, &raw); err != nil {
149			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
150		}
151		if len(raw.FormatVersion) == 0 {
152			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
153		}
154		if len(raw.ContentID) == 0 {
155			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
156		}
157		if len(raw.Graph) == 0 {
158			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
159		}
160		// An explicit JSON null is present-but-untyped and must not be silently
161		// treated as a zero value (in particular, graph:null must not read as an
162		// empty graph).
163		if isJSONNull(raw.FormatVersion) {
164			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
165		}
166		if isJSONNull(raw.ContentID) {
167			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
168		}
169		if isJSONNull(raw.Graph) {
170			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
171		}
172	
173		var version int
174		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
175			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
176		}
177		if version != SnapshotFormatVersion {
178			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
179		}
180	
181		var contentID string
182		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
183			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
184		}
185		if contentID == "" {
186			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
187		}
188	
189		var gf GraphFile
190		// The embedded graph obeys exactly the same name-encoding rule as a
191		// standalone graph file: a raw name literal with invalid UTF-8 bytes or an
192		// unpaired surrogate escape would be silently rewritten to U+FFFD, and a
193		// corrupted upstream could then resolve to a genuinely different dataset.
194		// The check runs on the graph's raw bytes and rejects the whole snapshot
195		// even when the declared content identifier happens to match the
196		// rewritten graph's digest. The raw scan is the shared one in
197		// name_encoding.go applied to the graph document scope.
198		if err := checkGraphNameEncoding(raw.Graph); err != nil {
199			return nil, err
200		}
201		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
202			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
203		}
204		// The embedded graph obeys exactly the same structural rules as a
205		// standalone graph file, so the two readers can never judge one graph
206		// differently.
207		adj, err := validateGraphStructureFromFile(gf.Datasets)
208		if err != nil {
209			return nil, err
210		}
211	
212		canonical, err := canonicalGraph(adj)
213		if err != nil {
214			return nil, err
215		}
216		if want := computeContentID(canonical); contentID != want {
217			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
218		}
219	
220		return &SnapshotFile{
221			FormatVersion: version,
222			ContentID:     contentID,
223			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
224		}, nil
225	}
226	
227	// checkDuplicateFields applies the shared repeated-known-field rule (see
228	// duplicate_fields.go) to a snapshot, supplying the snapshot's own field
229	// scope and locations: formatVersion, contentId, and graph at the top level,
230	// datasets inside graph, and name and upstreams inside each dataset record.
231	// The embedded graph is scanned by the same checkGraphObject a standalone
232	// graph file uses, so the two readers can never judge one graph differently.
233	func checkDuplicateFields(data []byte) error {
234		return runFieldScan(data, func(dec *json.Decoder) error {
235			return checkObjectFields(dec, "at the top level of the snapshot", []knownField{
236				{name: "formatVersion"},
237				{name: "contentId"},
238				{name: "graph", nested: func(dec *json.Decoder) error {
239					return checkGraphObject(dec, `in "graph"`)
240				}},
241			})
242		})
243	}
244	
245	// CompareSnapshots returns the fixed-direction diff from old to new. Both
246	// inputs are assumed to have passed ParseSnapshot; the report is fully
247	// deterministic and identical for semantically identical comparisons.
248	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
249		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
250		newAdj := adjacencyFromValidFile(newSnap.Graph)
251	
252		// Dataset-level changes follow the shared old -> new rule the batch report
253		// uses (see diffDatasets), so comparing two snapshots classifies new,
254		// removed, and directly changed datasets exactly the way previewing or
255		// applying the batch that turns one version into the other does.
256		newNodes, removedNodes, changedNodes := diffDatasets(oldAdj, newAdj)
257	
258		added, removed := diffRelations(oldAdj, newAdj)
259	
260		common := make([]string, 0)
261		for name := range oldAdj {
262			if _, ok := newAdj[name]; ok {
263				common = append(common, name)
264			}
265		}
266		sort.Strings(common)
267	
268		rootChanges := make([]RootSourceChange, 0)
269		for _, name := range common {
270			oldRoots := rootSources(name, oldAdj)
271			newRoots := rootSources(name, newAdj)
272			if !stringSliceEqual(oldRoots, newRoots) {
273				rootChanges = append(rootChanges, RootSourceChange{
274					Dataset:  name,
275					OldRoots: oldRoots,
276					NewRoots: newRoots,
277				})
278			}
279		}
280	
281		return &CompareReport{
282			NewDatasets:       orEmptyStrings(newNodes),
283			RemovedDatasets:   orEmptyStrings(removedNodes),
284			ChangedDatasets:   orEmptyStrings(changedNodes),
285			AddedRelations:    orEmptyRelations(added),
286			RemovedRelations:  orEmptyRelations(removed),
287			RootSourceChanges: rootChanges,
288		}
289	}
290	
291	// adjacencyFromValidFile builds normalized parent adjacency from an already
292	// validated graph file.
293	func adjacencyFromValidFile(gf GraphFile) adjacency {
294		adj := make(adjacency, len(gf.Datasets))
295		for _, ds := range gf.Datasets {
296			adj[ds.Name] = uniqueSorted(ds.Upstreams)
297		}
298		return adj
299	}
300	
301	// rootSources returns the root datasets reachable from node by following
302	// direct upstream edges. A node without upstreams is itself a root and its own
303	// source, so it is included. Nodes reached by more than one path count once.
304	// The result is sorted by name and never nil.
305	func rootSources(node string, adj adjacency) []string {
306		visited := make(map[string]bool)
307		var roots []string
308		var walk func(string)
309		walk = func(current string) {
310			if visited[current] {
311				return
312			}
313			visited[current] = true
314			parents := adj[current]
315			if len(parents) == 0 {
316				roots = append(roots, current)
317				return
318			}
319			for _, parent := range parents {
320				walk(parent)
321			}
322		}
323		walk(node)
324		sort.Strings(roots)
325		return orEmptyStrings(roots)
326	}
327	
328	func orEmptyStrings(s []string) []string {
329		if s == nil {
330			return []string{}
331		}
332		return s
333	}
334	
335	func orEmptyRelations(r []Relation) []Relation {
336		if r == nil {
337			return []Relation{}
338		}
339		return r
340	}
341

