1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"unicode/utf8"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	//
24	// Removals names datasets that must be absent from the final graph. Deleting a
25	// name that does not currently exist is a no-op (it is not reported as an
26	// actual removal), so a successful plan can be applied again with empty change
27	// and impact lists. A name listed in Removals must not also appear in Changes.
28	type Plan struct {
29		Changes  []PlanChange `json:"changes"`
30		Removals []string     `json:"removals"`
31	}
32	
33	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
34	// downstream dataset derives from the upstream dataset.
35	type Relation struct {
36		Upstream   string `json:"upstream"`
37		Downstream string `json:"downstream"`
38	}
39	
40	// GraphDataset is one dataset record in the on-disk graph JSON.
41	type GraphDataset struct {
42		Name      string   `json:"name"`
43		Upstreams []string `json:"upstreams"`
44	}
45	
46	// GraphFile is the on-disk JSON representation of a lineage graph.
47	type GraphFile struct {
48		Datasets []GraphDataset `json:"datasets"`
49	}
50	
51	// BatchReport is the deterministic report produced by preview and apply.
52	//
53	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
54	// lists are sorted by name byte order; relation lists are sorted by upstream
55	// then downstream.
56	type BatchReport struct {
57		FinalGraph          GraphFile  `json:"finalGraph"`
58		NewDatasets         []string   `json:"newDatasets"`
59		ChangedDatasets     []string   `json:"changedDatasets"`
60		RemovedDatasets     []string   `json:"removedDatasets"`
61		AddedRelations      []Relation `json:"addedRelations"`
62		RemovedRelations    []Relation `json:"removedRelations"`
63		AffectedDownstreams []string   `json:"affectedDownstreams"`
64	}
65	
66	// validatedGraphAdjacency is the single authority for whether an existing
67	// in-memory graph is legal, shared by the public ValidateGraph check and every
68	// operation that only reads an existing graph — preview and apply, graph
69	// export, and snapshot builds. It runs every structure rule once and returns
70	// the graph's canonical parent adjacency (sorted, duplicate-free):
71	//
72	//   - a nil map is ErrNotInitialized;
73	//   - dataset names and direct upstream references must be valid UTF-8 (the
74	//     encoding gate runs before anything quotes the names, so an unusable
75	//     upstream is never misreported as a missing one and its original bytes
76	//     stay readable in the error);
77	//   - nil lineage nodes and empty dataset names are rejected;
78	//   - every direct upstream must be a registered dataset, with the referrer
79	//     and the referenced name both in the error;
80	//   - the parent edges must be acyclic (self-dependency included), with the
81	//     datasets on the cycle named.
82	//
83	// The whole check is read-only: it builds fresh slices from each node's
84	// stored Parents and never touches the caller's nodes or their parent and
85	// child lists, including their order and duplicates. Whether the graph is
86	// legal depends solely on the dataset names and the direct-upstream
87	// relations: an initialized but empty graph is legal.
88	func validatedGraphAdjacency(graph map[string]*Lineage) (adjacency, error) {
89		if graph == nil {
90			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
91		}
92		if err := validateInMemoryNamesUTF8(graph); err != nil {
93			return nil, err
94		}
95		records := make([]GraphDataset, 0, len(graph))
96		for name, entry := range graph {
97			if entry == nil {
98				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
99			}
100			if name == "" {
101				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
102			}
103			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
104		}
105		adj, err := normalizeDatasets(records)
106		if err != nil {
107			return nil, err
108		}
109		return validateGraphAdjacency(adj)
110	}
111	
112	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
113	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
114	// references), missing upstreams, and cycles. It does not mutate the graph.
115	//
116	// A graph that fails validation cannot be used as the basis for a batch: an
117	// adjustment plan must not be allowed to paper over pre-existing corruption.
118	// This is the same judgment preview, apply, graph export, and snapshot builds
119	// make on the original graph (see validatedGraphAdjacency).
120	func ValidateGraph(graph map[string]*Lineage) error {
121		_, err := validatedGraphAdjacency(graph)
122		return err
123	}
124	
125	// validatePlanNamesUTF8 rejects a plan in which any name that takes part in
126	// the adjustment — a change record's name, one of its direct upstream names,
127	// or a removals entry — is not valid UTF-8. It is the in-memory counterpart
128	// of the raw-literal scan the plan reader runs (checkPlanNameEncoding): a
129	// Plan built directly in Go never passed through that reader, so without
130	// this gate PreviewBatch and ApplyBatch could register datasets the graph
131	// exporter must refuse and produce reports whose JSON silently rewrites the
132	// bad bytes to U+FFFD (two distinct corrupted names would then print as one).
133	//
134	// Plan order is checked as given: the name of record i comes before its
135	// upstreams, and removals follow all changes, so the first reported position
136	// is the earliest offending name the caller submitted. The error names the
137	// field ("name", "upstreams", or "removals"), the zero-based record or array
138	// position, and — for an upstream — its zero-based position inside that
139	// record. The offending name is quoted with %q, which renders the original
140	// bytes as \x escapes rather than replacing them with U+FFFD, so "p\xff" and
141	// "p\xfe" stay distinguishable. The plan is only read, never normalized or
142	// mutated. Register keeps accepting raw Go strings; this gate belongs only
143	// to the batch boundary, where an unusable name would enter a graph and a
144	// report that are promised exportable.
145	func validatePlanNamesUTF8(plan Plan) error {
146		for i, change := range plan.Changes {
147			if !utf8.ValidString(change.Name) {
148				return fmt.Errorf("%w: field %q in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
149					ErrInvalidArgument, "name", i, "changes", change.Name)
150			}
151			for j, upstream := range change.Upstreams {
152				if !utf8.ValidString(upstream) {
153					// Report the unusable name itself, never a missing-upstream
154					// error: the encoding defect takes precedence over whether
155					// the referenced dataset exists in the final graph.
156					return fmt.Errorf("%w: field %q at index %d in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
157						ErrInvalidArgument, "upstreams", j, i, "changes", upstream)
158				}
159			}
160		}
161		for i, name := range plan.Removals {
162			if !utf8.ValidString(name) {
163				return fmt.Errorf("%w: field %q at index %d contains invalid UTF-8 bytes: %q",
164					ErrInvalidArgument, "removals", i, name)
165			}
166		}
167		return nil
168	}
169	
170	// computeBatch validates the graph and plan, then computes the final adjacency
171	// and the diff report. It does not mutate graph. The returned adjacency is the
172	// graph as it will be after the batch; callers that want to commit it should
173	// pass it to applyAdjacency.
174	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
175		// One read of the existing graph settles both its legality and its
176		// canonical relations: the original graph must be legal even when the
177		// plan deletes a bad node or clears a dangling upstream, and the returned
178		// normalized adjacency is the basis the final graph is computed from.
179		original, err := validatedGraphAdjacency(graph)
180		if err != nil {
181			return nil, nil, err
182		}
183	
184		// Check every name the plan carries before anything that would quote it,
185		// hash it, or turn the report into JSON: the file reader already rejects
186		// these at the raw-literal level, but a plan constructed directly through
187		// the Go API bypasses that reader, and without this gate it could register
188		// a dataset whose name cannot be exported — two names differing only in an
189		// invalid byte ("p\xff" vs "p\xfe") would even render identically once the
190		// report is marshaled. This is the in-memory counterpart of the raw scan;
191		// see name_encoding.go.
192		if err := validatePlanNamesUTF8(plan); err != nil {
193			return nil, nil, err
194		}
195	
196		// Validate the plan: empty names and duplicate declarations reject the
197		// whole batch, naming the dataset and the reason.
198		declarations := make(map[string]int, len(plan.Changes))
199		for _, change := range plan.Changes {
200			if change.Name == "" {
201				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
202			}
203			declarations[change.Name]++
204			if declarations[change.Name] > 1 {
205				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
206			}
207		}
208	
209		// Validate removals: empty names, duplicate names, and names also declared
210		// as changes all reject the whole batch with the name and reason.
211		removalDecls := make(map[string]int, len(plan.Removals))
212		for _, name := range plan.Removals {
213			if name == "" {
214				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
215			}
216			removalDecls[name]++
217			if removalDecls[name] > 1 {
218				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
219			}
220			if _, ok := declarations[name]; ok {
221				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
222			}
223		}
224	
225		// Build the final adjacency: start from the original parents, replace each
226		// planned dataset's parents with its normalized upstreams. Being named in
227		// the plan does not by itself make a dataset new or changed — that is
228		// judged below by diffing the original and final graphs, exactly the way a
229		// snapshot comparison judges two versions.
230		final := make(adjacency, len(original)+len(plan.Changes))
231		for name, parents := range original {
232			final[name] = append([]string(nil), parents...)
233		}
234		for name := range removalDecls {
235			delete(final, name)
236		}
237		for _, change := range plan.Changes {
238			final[change.Name] = uniqueSorted(change.Upstreams)
239		}
240	
241		// The final graph obeys the same direct-upstream rule as an existing graph
242		// — every upstream a dataset names must exist in the graph being checked —
243		// but the rule is run here on the FINAL graph, after every add,
244		// replacement, and removal: datasets newly added in the same batch may
245		// reference one another regardless of plan order, while a retained dataset
246		// that still points at a removed name is rejected. The judgment itself is
247		// the shared firstMissingReference, so the two stages can never drift apart
248		// about what counts as a missing direct upstream; the final-graph wording
249		// (and the separate pass over the untouched original graph above) keeps
250		// the stages distinct. Sorted iteration inside the helper makes the
251		// reported (referrer, upstream) pair deterministic.
252		if referrer, referenced, missing := firstMissingReference(final); missing {
253			return nil, nil, finalGraphMissingReferenceError(referrer, referenced)
254		}
255		// The final graph must be acyclic, judged after all replacements.
256		if err := validateAcyclic(final); err != nil {
257			return nil, nil, err
258		}
259	
260		// Classify the dataset-level changes with the shared old -> new rule a
261		// snapshot comparison uses (see diffDatasets): only-in-final is new,
262		// only-in-original is removed, present-on-both is changed only when the
263		// direct upstream set actually differs. Deleting a name that does not
264		// exist is a no-op and is not reported, so a successful plan can be
265		// applied again with empty change and impact lists.
266		newNames, removedNames, changedNames := diffDatasets(original, final)
267	
268		added, removed := diffRelations(original, final)
269		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
270	
271		report := &BatchReport{
272			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
273			NewDatasets:         newNames,
274			ChangedDatasets:     changedNames,
275			RemovedDatasets:     removedNames,
276			AddedRelations:      added,
277			RemovedRelations:    removed,
278			AffectedDownstreams: affected,
279		}
280		// Guarantee non-nil slices so JSON encodes empty lists as [].
281		if report.NewDatasets == nil {
282			report.NewDatasets = []string{}
283		}
284		if report.ChangedDatasets == nil {
285			report.ChangedDatasets = []string{}
286		}
287		if report.RemovedDatasets == nil {
288			report.RemovedDatasets = []string{}
289		}
290		if report.AddedRelations == nil {
291			report.AddedRelations = []Relation{}
292		}
293		if report.RemovedRelations == nil {
294			report.RemovedRelations = []Relation{}
295		}
296		if report.AffectedDownstreams == nil {
297			report.AffectedDownstreams = []string{}
298		}
299		return report, final, nil
300	}
301	
302	// PreviewBatch validates the graph and plan and returns the report WITHOUT
303	// mutating graph. Preview and apply for the same graph and plan produce
304	// identical reports.
305	//
306	// As well as the structural plan rules (empty names, duplicate declarations,
307	// unresolvable upstreams, cycles), every name the plan carries — a change
308	// record's name, any of its direct upstreams, and every removals entry — must
309	// be valid UTF-8 even when the plan was constructed directly in Go instead of
310	// read by UnmarshalPlan. A name that is not valid UTF-8 rejects the whole
311	// batch with ErrInvalidArgument before any dataset could be registered or any
312	// report produced, so a success report can always be marshaled to JSON and an
313	// applied graph can always be exported. See validatePlanNamesUTF8.
314	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
315		report, _, err := computeBatch(graph, plan)
316		return report, err
317	}
318	
319	// ApplyBatch validates the plan, applies it to graph, and returns the report.
320	// On rejection — including a plan that names a dataset, upstream, or removal
321	// with bytes that are not valid UTF-8 — graph is left completely unchanged.
322	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
323		report, final, err := computeBatch(graph, plan)
324		if err != nil {
325			return nil, err
326		}
327		applyAdjacency(graph, final)
328		return report, nil
329	}
330	
331	// applyAdjacency rewrites the in-memory graph to match the final adjacency. It
332	// is the apply path of the shared relationship rule in materializeLineage, the
333	// same rule a graph reader follows: nodes absent from final are removed,
334	// parents are replaced wholesale with independent copies, and children are
335	// rebuilt from the parent edges. Surviving *Lineage records are updated in
336	// place, so node pointers a Go caller already holds expose the new
337	// relationships after the batch returns.
338	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
339		materializeLineage(graph, final)
340	}
341	
342	// diffDatasets is the single authority for classifying dataset-level changes
343	// between two versions of a graph, shared by the batch report (preview and
344	// apply) and the snapshot comparison so both can never disagree about the
345	// rule. Changes are always judged in the direction original -> final:
346	//
347	//   - a dataset present only in final is NEW — even when it arrives carrying
348	//     upstreams, it is never also listed as changed;
349	//   - a dataset present only in original is REMOVED — a removed dataset is
350	//     never also listed as an upstream change;
351	//   - a dataset present on both sides is CHANGED only when its direct
352	//     upstream set actually differs; a dataset whose upstreams were cleared
353	//     still exists (as a root), so it is changed, not removed.
354	//
355	// Names are case-sensitive and compared verbatim; only the name set and each
356	// dataset's normalized upstream set matter, never record order, upstream
357	// order, or duplicate upstreams. Each returned list is sorted by name byte
358	// order and is nil when empty; callers normalize nil to [] for JSON.
359	func diffDatasets(original, final adjacency) (newNames, removedNames, changedNames []string) {
360		for name, finalParents := range final {
361			if originalParents, ok := original[name]; !ok {
362				newNames = append(newNames, name)
363			} else if !stringSliceEqual(originalParents, finalParents) {
364				changedNames = append(changedNames, name)
365			}
366		}
367		for name := range original {
368			if _, ok := final[name]; !ok {
369				removedNames = append(removedNames, name)
370			}
371		}
372		sort.Strings(newNames)
373		sort.Strings(removedNames)
374		sort.Strings(changedNames)
375		return newNames, removedNames, changedNames
376	}
377	
378	// diffRelations returns the directed edges present in final but not original
379	// (added) and present in original but not final (removed). Both lists are
380	// sorted by upstream then downstream.
381	func diffRelations(original, final adjacency) (added, removed []Relation) {
382		origEdges := edgeSet(original)
383		finalEdges := edgeSet(final)
384		for e := range finalEdges {
385			if !origEdges[e] {
386				added = append(added, e)
387			}
388		}
389		for e := range origEdges {
390			if !finalEdges[e] {
391				removed = append(removed, e)
392			}
393		}
394		sortRelations(added)
395		sortRelations(removed)
396		return added, removed
397	}
398	
399	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
400	func edgeSet(adj adjacency) map[Relation]bool {
401		set := make(map[Relation]bool)
402		for downstream, parents := range adj {
403			for _, upstream := range parents {
404				set[Relation{Upstream: upstream, Downstream: downstream}] = true
405			}
406		}
407		return set
408	}
409	
410	// sortRelations sorts by upstream then downstream.
411	func sortRelations(rels []Relation) {
412		sort.Slice(rels, func(i, j int) bool {
413			if rels[i].Upstream != rels[j].Upstream {
414				return rels[i].Upstream < rels[j].Upstream
415			}
416			return rels[i].Downstream < rels[j].Downstream
417		})
418	}
419	
420	// affectedDownstreams computes the impact set: starting from the seed datasets
421	// (new, actually changed, or actually removed), follow downstream (children)
422	// edges in BOTH the original and the final graphs. Datasets that are
423	// themselves seeds are excluded from the output; every other reachable dataset
424	// is included once.
425	//
426	// Walking both graphs matters when relations are deleted: a dataset that was
427	// reachable downstream before the change (and thus loses a lineage path) is
428	// still affected even if the edge is gone in the final graph. Removed datasets
429	// are seeds too, so a downstream that lost its upstream node is counted.
430	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
431		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
432		for _, name := range newNames {
433			seeds[name] = true
434		}
435		for _, name := range changedNames {
436			seeds[name] = true
437		}
438		for _, name := range removedNames {
439			seeds[name] = true
440		}
441	
442		origChildren := invertAdjacency(original)
443		finalChildren := invertAdjacency(final)
444	
445		seen := make(map[string]bool)
446		queue := make([]string, 0, len(seeds))
447		for seed := range seeds {
448			queue = append(queue, seed)
449		}
450		for len(queue) > 0 {
451			node := queue[0]
452			queue = queue[1:]
453			for _, child := range origChildren[node] {
454				if !seen[child] {
455					seen[child] = true
456					queue = append(queue, child)
457				}
458			}
459			for _, child := range finalChildren[node] {
460				if !seen[child] {
461					seen[child] = true
462					queue = append(queue, child)
463				}
464			}
465		}
466	
467		out := make([]string, 0, len(seen))
468		for name := range seen {
469			if !seeds[name] {
470				out = append(out, name)
471			}
472		}
473		sort.Strings(out)
474		return out
475	}
476	
477	// invertAdjacency maps each dataset to the datasets that depend on it (its
478	// children), with each child list sorted by name.
479	func invertAdjacency(adj adjacency) map[string][]string {
480		children := make(map[string][]string, len(adj))
481		for name, parents := range adj {
482			for _, parent := range parents {
483				children[parent] = append(children[parent], name)
484			}
485		}
486		for name := range children {
487			sort.Strings(children[name])
488		}
489		return children
490	}
491	
492	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
493	// records with non-nil upstream lists.
494	func adjacencyToDatasets(adj adjacency) []GraphDataset {
495		names := make([]string, 0, len(adj))
496		for name := range adj {
497			names = append(names, name)
498		}
499		sort.Strings(names)
500		ds := make([]GraphDataset, 0, len(names))
501		for _, name := range names {
502			parents := adj[name]
503			if parents == nil {
504				parents = []string{}
505			}
506			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
507		}
508		return ds
509	}
510	
511	// stringSliceEqual reports whether a and b contain the same strings in the
512	// same order. Both are expected to be sorted and duplicate-free.
513	func stringSliceEqual(a, b []string) bool {
514		if len(a) != len(b) {
515			return false
516		}
517		for i := range a {
518			if a[i] != b[i] {
519				return false
520			}
521		}
522		return true
523	}
524	
525	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
526	// The graph must satisfy every structure rule a reader enforces; nil nodes,
527	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
528	// references), missing upstreams, and dependency cycles (including a dataset
529	// that lists itself) reject the export with no bytes returned, so a successful
530	// result can always be read back with UnmarshalGraphFile. The check is
531	// read-only: the in-memory graph is never modified.
532	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
533		adj, err := validatedGraphAdjacency(graph)
534		if err != nil {
535			return nil, err
536		}
537		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
538		return json.MarshalIndent(gf, "", "  ")
539	}
540	
541	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
542	// graph (parents and derived children). The graph is checked with the same
543	// structural rules a snapshot enforces (empty names, duplicate datasets,
544	// missing upstreams, and cycles); a structurally invalid graph is rejected so
545	// it cannot be used as the basis for a batch. As in a snapshot, a known field
546	// declared twice within the same object — datasets in the graph object, name
547	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
548	// even when the duplicates carry identical values.
549	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
550		if err := checkGraphFileDuplicateFields(data); err != nil {
551			return nil, err
552		}
553		// Every name the graph carries must survive decoding exactly as written:
554		// a raw literal with invalid UTF-8 bytes or an unpaired surrogate escape
555		// would be silently rewritten to U+FFFD by json.Unmarshal, and a corrupted
556		// upstream could then resolve to a genuinely different dataset (an edge
557		// written as "源" plus a lone \uD800 would point at the real dataset
558		// "源�"). See name_encoding.go.
559		if err := checkGraphNameEncoding(data); err != nil {
560			return nil, err
561		}
562		var gf GraphFile
563		if err := json.Unmarshal(data, &gf); err != nil {
564			return nil, fmt.Errorf("invalid graph JSON: %w", err)
565		}
566		adj, err := validateGraphStructureFromFile(gf.Datasets)
567		if err != nil {
568			return nil, err
569		}
570		// Rebuild children from the parent edges so the in-memory graph is
571		// consistent regardless of how the file was produced.
572		return lineageFromAdjacency(adj), nil
573	}
574	
575	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
576	// duplicate declarations) is validated later by computeBatch so that preview
577	// and apply share identical rejection behavior.
578	//
579	// A known field declared twice within the same object — changes or removals
580	// at the top level, name or upstreams inside one change record — is
581	// ambiguous: the reader would silently keep only the last declaration and
582	// drop the earlier adjustment. The whole plan is refused instead, even when
583	// the duplicates carry identical values, one is null, or the surviving value
584	// is a legal empty list. Field names are recognized the same way the decoder
585	// resolves them (after JSON unescaping, with Unicode case folding), so a
586	// second declaration spelled "Changes" or "changes" still collides;
587	// dataset names themselves stay case-sensitive. Unknown fields keep their
588	// ignore-everything behavior and may repeat freely.
589	//
590	// Every name that takes part in the adjustment — each change record's name,
591	// every upstreams entry, and every removals entry — must also survive
592	// decoding exactly as written: a raw string literal carrying bytes that are
593	// not valid UTF-8, or a \u escape forming an unpaired surrogate, would be
594	// silently rewritten to U+FFFD by the decoder, and the corrupted name could
595	// then collide with a genuinely different dataset (a removals entry meant
596	// for no one could delete the dataset really named "�"). The whole plan is
597	// refused instead, naming the field and the zero-based record or array
598	// position, even when the corrupted name would only have matched a dataset
599	// that does not exist. A genuine "�", correctly paired surrogate escapes,
600	// and names that merely look like escapes (a backslash before an ordinary
601	// letter) stay legal; unknown fields and their nested strings are not
602	// checked. The raw scan is shared with the graph readers and lives in
603	// name_encoding.go; this file only supplies the plan document scope.
604	func UnmarshalPlan(data []byte) (Plan, error) {
605		var p Plan
606		if err := checkPlanDuplicateFields(data); err != nil {
607			return p, err
608		}
609		if err := json.Unmarshal(data, &p); err != nil {
610			return p, fmt.Errorf("invalid plan JSON: %w", err)
611		}
612		if err := checkPlanNameEncoding(data); err != nil {
613			return Plan{}, err
614		}
615		return p, nil
616	}
617	
618	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
619	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
620	// file's own location: datasets may be declared only once in the top-level
621	// graph object, and name and upstreams only once in each dataset record. The
622	// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
623	// so preview, apply, and snapshot can never disagree about a graph that
624	// repeats a known field.
625	func checkGraphFileDuplicateFields(data []byte) error {
626		return runFieldScan(data, func(dec *json.Decoder) error {
627			return checkGraphObject(dec, "at the top level of the graph")
628		})
629	}
630	
631	// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
632	// duplicate_fields.go) to a plan, supplying the plan's own field scope and
633	// locations: changes or removals at the top level, and name or upstreams
634	// inside each change record. A change record carries the same fields as a
635	// dataset record, so both use the shared datasetRecordFields scope and a plan
636	// can never be judged differently from the other documents about what counts
637	// as a repeated field.
638	func checkPlanDuplicateFields(data []byte) error {
639		return runFieldScan(data, func(dec *json.Decoder) error {
640			return checkObjectFields(dec, "at the top level of the plan", []knownField{
641				{name: "changes", nested: func(dec *json.Decoder) error {
642					return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
643						return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
644					})
645				}},
646				{name: "removals"},
647			})
648		})
649	}
