1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file holds the single object-walking rule shared by the two raw-JSON
4	// checks every reader runs over the documents it understands (snapshot,
5	// standalone graph file, and adjustment plan):
6	//
7	//   - The repeated-known-field rule: within one object, a field the reader
8	//     recognizes may be declared only once. A repeated declaration is
9	//     ambiguous — the regular decoder would silently keep only the last
10	//     value — so the whole document is refused, even when the duplicates
11	//     carry identical values, the first is null, or the surviving value
12	//     would pass every other check.
13	//   - The raw name-encoding rule (name_encoding.go) validates, in its own
14	//     pass, each name the document carries against its raw string literal.
15	//
16	// The two checks run as separate passes in each reader's fixed order, but
17	// traverse objects with exactly the same walk below: keys are recognized
18	// after JSON unescaping with Unicode case folding, a known field whose value
19	// nests another checked object or array is descended into, and every other
20	// value — unknown fields included, with everything nested inside them — is
21	// skipped. Unknown fields keep their ignore-everything behavior and may
22	// repeat freely; their duplicate keys, keys that merely spell a known field,
23	// and corrupt strings never reach either check.
24	//
25	// Each document supplies only its own field scope (which keys are known at
26	// each level, and which known field's value nests another checked object or
27	// array) and its own error locations; the walking and matching below are
28	// common, so the readers can never drift apart about which fields are known,
29	// how a record is read, or what counts as a duplicate.
30	//
31	// Matching rules, common to every document:
32	//
33	//   - Field names are compared after JSON string unescaping and with the same
34	//     Unicode simple case-folding the decoder applies to its case-insensitive
35	//     field lookup (strings.EqualFold), so "name" and "Name" collide, and so
36	//     do spellings that only differ in a fold-equivalent rune such as
37	//     "dataſets" (long s) and "datasets". Dataset names themselves stay
38	//     case-sensitive; this folding applies to field names only.
39	//   - The decoder uses UseNumber so numbers are kept verbatim instead of being
40	//     converted to float64: a perfectly legal JSON number outside the float64
41	//     range (such as 1e400), even one buried in an ignored unknown field's
42	//     value, must not make the decoder error out and abort the scan —
43	//     otherwise an unrelated large number placed before a repeated known
44	//     field would hide that duplication. Malformed number syntax still fails
45	//     and is left to the regular parse to report.
46	//   - A document too malformed to keep walking aborts the scan; the regular
47	//     parse then reports the syntax or type error instead, so this check
48	//     never changes how invalid JSON fails.
49	package chainledger
50	
51	import (
52		"bytes"
53		"encoding/json"
54		"errors"
55		"fmt"
56		"strings"
57	)
58	
59	// errAbortScan stops the duplicate-field scan when the document is too
60	// malformed to keep walking; the regular parse then reports the syntax or
61	// type error instead.
62	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
63	
64	// runFieldScan runs check over data with the scan decoder (UseNumber, so an
65	// oversized-but-legal number anywhere in the document cannot abort the walk).
66	// An aborted scan is not an error: the document is left to the regular parse,
67	// which reports the structural problem.
68	func runFieldScan(data []byte, check func(dec *json.Decoder) error) error {
69		dec := json.NewDecoder(bytes.NewReader(data))
70		dec.UseNumber()
71		if err := check(dec); err != nil && !errors.Is(err, errAbortScan) {
72			return err
73		}
74		return nil
75	}
76	
77	// knownField is one field an object reader recognizes: name is the canonical
78	// spelling reported in duplicate errors (matching is case-folded, so any
79	// equivalent spelling selects it), and nested, when non-nil, checks the
80	// field's value as another checked object or array. A known field without a
81	// nested check has its value skipped like any unknown field's.
82	type knownField struct {
83		name   string
84		nested func(dec *json.Decoder) error
85	}
86	
87	// matchKnownField returns the known field key selects, matching the decoder's
88	// case-insensitive field lookup, or nil if key is unknown.
89	func matchKnownField(key string, fields []knownField) *knownField {
90		for i := range fields {
91			if strings.EqualFold(key, fields[i].name) {
92				return &fields[i]
93			}
94		}
95		return nil
96	}
97	
98	// checkObjectFields runs the once-only pass of the shared object walk: each
99	// known field may be declared at most once, and a second declaration of one
100	// — matched case-folded, even when the two values are identical, one is
101	// null, or one is an empty list — rejects the whole document. location
102	// describes the object itself in the duplicate error. A value that is not an
103	// object is consumed and left for the regular parse to report.
104	func checkObjectFields(dec *json.Decoder, location string, fields []knownField) error {
105		seen := make(map[string]bool, len(fields))
106		return walkKnownObject(dec, fields, func(field *knownField) error {
107			if seen[field.name] {
108				return duplicateFieldError(field.name, location)
109			}
110			seen[field.name] = true
111			return nil
112		})
113	}
114	
115	// checkArrayElements scans the array the decoder is positioned at, running
116	// check on every element with its zero-based index. A value that is not an
117	// array is consumed and left for the regular parse to report.
118	func checkArrayElements(dec *json.Decoder, check func(dec *json.Decoder, index int) error) error {
119		tok, err := scanToken(dec)
120		if err != nil {
121			return err
122		}
123		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
124			return skipRest(dec, tok) // not an array: the regular parse reports it
125		}
126		for index := 0; dec.More(); index++ {
127			if err := check(dec, index); err != nil {
128				return err
129			}
130		}
131		_, err = scanToken(dec) // closing ']'
132		return err
133	}
134	
135	// walkKnownObject is the one object traversal shared by both raw-JSON checks.
136	// It walks the object the decoder is positioned at: keys are matched after
137	// JSON unescaping with Unicode case folding; every time a key selects a
138	// known field, onKnown is invoked with that field (it enforces the once-only
139	// rule in a duplicate pass and is nil in a name-encoding pass), and then a
140	// known field with a nested checker is descended into while every other
141	// value — an unknown field, or a known field without a nested checker — is
142	// skipped together with whatever it nests. Without the once-only rule a
143	// recognized field is reached on every occurrence; with it, onKnown rejects
144	// the second one before its value is examined. A value that is not an object
145	// is consumed and left for the regular parse to report.
146	func walkKnownObject(dec *json.Decoder, fields []knownField, onKnown func(field *knownField) error) error {
147		tok, err := scanToken(dec)
148		if err != nil {
149			return err
150		}
151		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
152			return skipRest(dec, tok) // not an object: the regular parse reports it
153		}
154		for dec.More() {
155			key, err := scanKey(dec)
156			if err != nil {
157				return err
158			}
159			if field := matchKnownField(key, fields); field != nil {
160				if onKnown != nil {
161					if err := onKnown(field); err != nil {
162						return err
163					}
164				}
165				if field.nested != nil {
166					if err := field.nested(dec); err != nil {
167						return err
168					}
169					continue
170				}
171			}
172			// Unknown field, or a known field without a value checker: ignored
173			// with everything nested inside it.
174			if err := skipValue(dec); err != nil {
175				return err
176			}
177		}
178		_, err = scanToken(dec) // closing '}'
179		return err
180	}
181	
182	// scanObjectFields runs the name-encoding pass of walkKnownObject WITHOUT the
183	// once-only rule: a recognized field's value checker runs on every
184	// occurrence instead of rejecting the second one. The raw name-encoding
185	// scan (name_encoding.go) uses this walker; it runs only after the
186	// duplicate-field scan has already rejected repeated known fields, while it
187	// must still validate the literals of every known value the document carries.
188	// A value that is not an object is consumed and left for the regular parse.
189	func scanObjectFields(dec *json.Decoder, fields []knownField) error {
190		return walkKnownObject(dec, fields, nil)
191	}
192	
193	// datasetRecordFields is the field scope of one dataset record — the same
194	// shape whether the record sits in a graph's "datasets" array or in a plan's
195	// "changes" array — so both readers judge one record identically.
196	var datasetRecordFields = []knownField{{name: "name"}, {name: "upstreams"}}
197	
198	// checkGraphObject scans one graph object wherever it appears (the top level
199	// of a standalone graph file, or the "graph" value inside a snapshot):
200	// datasets may be declared only once, and each record of the datasets array
201	// is checked for repeated name/upstreams declarations. location names the
202	// graph object itself in the duplicate error.
203	func checkGraphObject(dec *json.Decoder, location string) error {
204		return checkObjectFields(dec, location, []knownField{
205			{name: "datasets", nested: func(dec *json.Decoder) error {
206				return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
207					return checkObjectFields(dec, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index), datasetRecordFields)
208				})
209			}},
210		})
211	}
212	
213	// duplicateFieldError reports a known field declared twice, naming the field
214	// and where in the document the repetition occurred.
215	func duplicateFieldError(field, location string) error {
216		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
217	}
218	
219	// scanToken reads one token; any decode failure aborts the scan so the
220	// regular parse can report the malformed document.
221	func scanToken(dec *json.Decoder) (json.Token, error) {
222		tok, err := dec.Token()
223		if err != nil {
224			return nil, errAbortScan
225		}
226		return tok, nil
227	}
228	
229	// scanKey reads the next key of the object currently being walked.
230	func scanKey(dec *json.Decoder) (string, error) {
231		tok, err := scanToken(dec)
232		if err != nil {
233			return "", err
234		}
235		key, ok := tok.(string)
236		if !ok {
237			return "", errAbortScan
238		}
239		return key, nil
240	}
241	
242	// skipValue consumes one complete JSON value.
243	func skipValue(dec *json.Decoder) error {
244		tok, err := scanToken(dec)
245		if err != nil {
246			return err
247		}
248		return skipRest(dec, tok)
249	}
250	
251	// skipRest consumes the remainder of a value whose first token is tok.
252	func skipRest(dec *json.Decoder, tok json.Token) error {
253		delim, ok := tok.(json.Delim)
254		if !ok {
255			return nil // scalar, fully consumed already
256		}
257		var closer json.Delim
258		switch delim {
259		case '{':
260			closer = '}'
261			for dec.More() {
262				if _, err := scanKey(dec); err != nil {
263					return err
264				}
265				if err := skipValue(dec); err != nil {
266					return err
267				}
268			}
269		case '[':
270			closer = ']'
271			for dec.More() {
272				if err := skipValue(dec); err != nil {
273					return err
274				}
275			}
276		default:
277			return errAbortScan
278		}
279		tok, err := scanToken(dec)
280		if err != nil {
281			return err
282		}
283		if end, ok := tok.(json.Delim); !ok || end != closer {
284			return errAbortScan
285		}
286		return nil
287	}
