1	package chainledger
2	
3	import (
4		"encoding/json"
5		"errors"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// TestReadersShareGraphStructureRules is a parity guard for the consolidation:
12	// the standalone graph file reader and the snapshot graph reader must agree on
13	// every graph's validity, on the sentinel error category when invalid, and on
14	// the normalized graph when valid.
15	func TestReadersShareGraphStructureRules(t *testing.T) {
16		graphs := map[string]string{
17			"empty":                 `{"datasets":[]}`,
18			"single root":           `{"datasets":[{"name":"A","upstreams":[]}]}`,
19			"chain shuffled":        `{"datasets":[{"name":"C","upstreams":["B","A","B"]},{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`,
20			"case and spaces":       `{"datasets":[{"name":" A ","upstreams":[]},{"name":"a","upstreams":[" A "]}]}`,
21			"empty name":            `{"datasets":[{"name":"","upstreams":[]}]}`,
22			"duplicate dataset":     `{"datasets":[{"name":"A","upstreams":[]},{"name":"A","upstreams":[]}]}`,
23			"missing upstream":      `{"datasets":[{"name":"A","upstreams":["ghost"]}]}`,
24			"direct self cycle":     `{"datasets":[{"name":"A","upstreams":["A"]}]}`,
25			"indirect cycle":        `{"datasets":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`,
26			"empty upstream string": `{"datasets":[{"name":"A","upstreams":[""]}]}`,
27			"datasets field twice":  `{"datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
28			"name field twice":      `{"datasets":[{"name":"A","name":"A","upstreams":[]}]}`,
29			"upstreams field twice": `{"datasets":[{"name":"A","upstreams":[],"upstreams":[]}]}`,
30		}
31	
32		category := func(err error) string {
33			switch {
34			case err == nil:
35				return ""
36			case errors.Is(err, ErrInvalidArgument):
37				return "invalid"
38			case errors.Is(err, ErrNotFound):
39				return "notfound"
40			case errors.Is(err, ErrCycle):
41				return "cycle"
42			default:
43				return "other"
44			}
45		}
46	
47		for name, data := range graphs {
48			t.Run(name, func(t *testing.T) {
49				fileGraph, fileErr := UnmarshalGraphFile([]byte(data))
50	
51				// For a valid graph, marshal a correctly-addressed snapshot so the
52				// snapshot-only content-id rule passes and only the shared graph
53				// rules are exercised. For an invalid graph the structure is
54				// rejected before content-id integrity, so a dummy id suffices.
55				var snapDoc []byte
56				if fileErr == nil {
57					b, err := MarshalSnapshot(snapshotOf(t, data))
58					if err != nil {
59						t.Fatalf("marshal snapshot: %v", err)
60					}
61					snapDoc = b
62				} else {
63					snapDoc = []byte(`{"formatVersion":1,"contentId":"sha256:deadbeef","graph":` + data + `}`)
64				}
65				snap, snapErr := ParseSnapshot(snapDoc)
66	
67				if category(fileErr) != category(snapErr) {
68					t.Fatalf("category mismatch: file=%v snapshot=%v", fileErr, snapErr)
69				}
70				if fileErr != nil {
71					return
72				}
73	
74				// Valid graph: both readers keep the same normalized graph.
75				fileAdj, err := validatedGraphAdjacency(fileGraph)
76				if err != nil {
77					t.Fatalf("validatedGraphAdjacency: %v", err)
78				}
79				fileBytes, err := json.Marshal(GraphFile{Datasets: adjacencyToDatasets(fileAdj)})
80				if err != nil {
81					t.Fatalf("marshal file graph: %v", err)
82				}
83				snapAdj := adjacencyFromValidFile(snap.Graph)
84				snapBytes, err := json.Marshal(GraphFile{Datasets: adjacencyToDatasets(snapAdj)})
85				if err != nil {
86					t.Fatalf("marshal snapshot graph: %v", err)
87				}
88				if !reflect.DeepEqual(fileBytes, snapBytes) {
89					t.Fatalf("normalized graph differs:\n file %s\n snap %s", fileBytes, snapBytes)
90				}
91			})
92		}
93	}
94	
95	// TestFirstMissingReferenceOrdering guards the single shared direct-upstream
96	// rule: with several dangling edges present at once, the reported pair is the
97	// referrer first by name byte order, then that referrer's first missing
98	// upstream by byte order — regardless of map iteration, record order, or
99	// upstream input order. Case and surrounding whitespace are kept verbatim and
100	// a repeated upstream is one relationship.
101	func TestFirstMissingReferenceOrdering(t *testing.T) {
102		// Adjacency values are normalized as every production caller builds them;
103		// uniqueSorted makes the repeated upstream one relationship and sorts
104		// names, so neither upstream input order nor the duplicate can change the
105		// reported pair. Map order is deliberately scrambled relative to byte
106		// order.
107		adj := adjacency{
108			"b": {"aaa", "zzz"},
109			"A": {"B", "ghost"}, // 0x41 sorts before lowercase 0x62
110			// " A" (leading space, 0x20) sorts before "A".
111			" A": uniqueSorted([]string{"later-missing", "aaa-missing", "aaa-missing"}),
112		}
113		referrer, referenced, ok := firstMissingReference(adj)
114		if !ok {
115			t.Fatal("firstMissingReference found no missing reference")
116		}
117		if referrer != " A" || referenced != "aaa-missing" {
118			t.Fatalf("first pair = (%q, %q), want (%q, %q)", referrer, referenced, " A", "aaa-missing")
119		}
120	
121		// An empty graph and a graph with only roots have no missing reference.
122		for name, empty := range map[string]adjacency{
123			"empty graph":  {},
124			"roots only":   {"A": nil, "B": {}},
125			"resolved all": {"A": {}, "B": {"A"}},
126		} {
127			if _, _, ok := firstMissingReference(empty); ok {
128				t.Errorf("%s unexpectedly reported a missing reference", name)
129			}
130		}
131	}
132	
133	// TestMissingReferenceStagesShareTheRule is a parity guard for the
134	// consolidation: an existing graph and a batch's final graph apply the same
135	// direct-upstream rule (same pair, ErrNotFound in both) while staying two
136	// stages with their own wording — "not registered" for the graph being read,
137	// "does not exist in the final graph" for the batch result.
138	func TestMissingReferenceStagesShareTheRule(t *testing.T) {
139		const (
140			existingWording = "which is not registered"
141			finalWording    = "which does not exist in the final graph"
142		)
143	
144		t.Run("existing graph", func(t *testing.T) {
145			graph := map[string]*Lineage{
146				// B sorts after A; the shared rule must report A's missing upstream
147				// first even though B is constructed first here.
148				"B": {Dataset: "B", Parents: []string{"also-gone"}},
149				"A": {Dataset: "A", Parents: []string{"zzz-gone", "aaa-gone"}},
150			}
151			err := ValidateGraph(graph)
152			if !errors.Is(err, ErrNotFound) {
153				t.Fatalf("ValidateGraph err = %v, want ErrNotFound", err)
154			}
155			msg := err.Error()
156			for _, want := range []string{`"A"`, `"aaa-gone"`, existingWording} {
157				if !strings.Contains(msg, want) {
158					t.Errorf("error %q missing %q", msg, want)
159				}
160			}
161			if strings.Contains(msg, finalWording) {
162				t.Errorf("existing-graph error used final-graph wording: %q", msg)
163			}
164		})
165	
166		t.Run("batch final graph", func(t *testing.T) {
167			// Start from a legal graph; the plan removes "A" while two retained
168			// datasets still reference names that will not exist in the final
169			// graph. The pair ordering comes from the shared rule, and the error
170			// keeps the final-graph wording.
171			graph := map[string]*Lineage{
172				"A": {Dataset: "A"},
173				"B": {Dataset: "B", Parents: []string{"A"}},
174				"C": {Dataset: "C", Parents: []string{"A"}},
175			}
176			plan := Plan{Removals: []string{"A"}}
177			_, err := PreviewBatch(graph, plan)
178			if !errors.Is(err, ErrNotFound) {
179				t.Fatalf("PreviewBatch err = %v, want ErrNotFound", err)
180			}
181			msg := err.Error()
182			// B < C byte order; A is the only missing upstream of B.
183			for _, want := range []string{`"B"`, `"A"`, finalWording} {
184				if !strings.Contains(msg, want) {
185					t.Errorf("error %q missing %q", msg, want)
186				}
187			}
188			if strings.Contains(msg, existingWording) {
189				t.Errorf("final-graph error used existing-graph wording: %q", msg)
190			}
191		})
192	}
193	
194	// TestUnmarshalGraphFileRejectsDuplicateFields: a known field declared twice
195	// within the same object makes the whole graph file ambiguous and must be
196	// rejected, even when the duplicates carry identical values, the first is
197	// null, or the surviving value alone would form a legal graph. Field names
198	// are recognized after JSON unescaping and with the decoder's Unicode case
199	// folding, so escaped or fold-equivalent spellings of a second declaration
200	// still collide.
201	func TestUnmarshalGraphFileRejectsDuplicateFields(t *testing.T) {
202		const (
203			longS       = "ſ" // U+017F LATIN SMALL LETTER LONG S, folds to ASCII "s"
204			longSEscape = "\\" + "u017f"
205		)
206	
207		cases := map[string]struct {
208			data     string
209			field    string
210			location string
211		}{
212			"datasets twice identical": {
213				`{"datasets":[{"name":"A","upstreams":[]}],"datasets":[{"name":"A","upstreams":[]}]}`,
214				"datasets", "top level",
215			},
216			"real datasets then empty replacement": {
217				`{"datasets":[{"name":"A","upstreams":[]}],"datasets":[]}`,
218				"datasets", "top level",
219			},
220			"null datasets then real": {
221				`{"datasets":null,"datasets":[{"name":"A","upstreams":[]}]}`,
222				"datasets", "top level",
223			},
224			"name twice same value": {
225				`{"datasets":[{"name":"A","name":"A","upstreams":[]}]}`,
226				"name", `index 0 of "datasets"`,
227			},
228			"null name then valid": {
229				`{"datasets":[{"name":null,"name":"A","upstreams":[]}]}`,
230				"name", `index 0 of "datasets"`,
231			},
232			"upstreams then empty would look like root": {
233				`{"datasets":[{"name":"B","upstreams":["A"],"upstreams":[]},{"name":"A","upstreams":[]}]}`,
234				"upstreams", `index 0 of "datasets"`,
235			},
236			"null upstreams then valid": {
237				`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":null,"upstreams":["A"]}]}`,
238				"upstreams", `index 1 of "datasets"`,
239			},
240			"escaped name key": {
241				`{"datasets":[{"na\u006de":"A","name":"A","upstreams":[]}]}`,
242				"name", `index 0 of "datasets"`,
243			},
244			"case variant name": {
245				`{"datasets":[{"Name":"A","name":"A","upstreams":[]}]}`,
246				"name", `index 0 of "datasets"`,
247			},
248			"case variant datasets": {
249				`{"Datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
250				"datasets", "top level",
251			},
252			"case variant upstreams": {
253				`{"datasets":[{"name":"A","UPSTREAMS":[],"upstreams":[]}]}`,
254				"upstreams", `index 0 of "datasets"`,
255			},
256			"long s datasets": {
257				`{"data` + longS + `ets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
258				"datasets", "top level",
259			},
260			"long s upstreams via JSON escape": {
261				`{"datasets":[{"name":"A","up` + longSEscape + `treams":[],"upstreams":[]}]}`,
262				"upstreams", `index 0 of "datasets"`,
263			},
264			"big number in unknown field before duplicated datasets": {
265				`{"note":1e400,"datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
266				"datasets", "top level",
267			},
268			"big number nested in record before duplicated upstreams": {
269				`{"datasets":[{"name":"A","vals":{"deep":[1e999]},"upstreams":[],"upstreams":[]}]}`,
270				"upstreams", `index 0 of "datasets"`,
271			},
272		}
273		for name, tc := range cases {
274			t.Run(name, func(t *testing.T) {
275				// Every "escape" case really must carry ASCII escape bytes.
276				if strings.Contains(name, "escape") && !strings.Contains(tc.data, longSEscape) && !strings.Contains(tc.data, `\u006d`) {
277					t.Fatalf("test case %q does not actually use a JSON escape", name)
278				}
279				_, err := UnmarshalGraphFile([]byte(tc.data))
280				if !errors.Is(err, ErrInvalidArgument) {
281					t.Fatalf("err = %v, want ErrInvalidArgument", err)
282				}
283				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
284					t.Errorf("err = %q, want it to name duplicated field %q", err, tc.field)
285				}
286				if !strings.Contains(err.Error(), tc.location) {
287					t.Errorf("err = %q, want it to locate the duplicate %q", err, tc.location)
288				}
289			})
290		}
291	}
292	
293	// TestUnmarshalGraphFileDuplicateTolerances: repetitions that do NOT create
294	// ambiguity stay legal — unknown fields may repeat anywhere (even holding
295	// duplicate keys or oversized numbers inside), each dataset record declares
296	// its own name, and duplicate names inside one upstreams array still count as
297	// one relationship. A known field written once in a case-variant or
298	// fold-equivalent spelling is still recognized.
299	func TestUnmarshalGraphFileDuplicateTolerances(t *testing.T) {
300		cases := map[string]string{
301			"empty graph":                     `{"datasets":[]}`,
302			"unknown top-level field repeats": `{"meta":"x","meta":"y","datasets":[{"name":"A","upstreams":[]}]}`,
303			"unknown record field repeats":    `{"datasets":[{"name":"A","note":1,"note":2,"upstreams":[]}]}`,
304			"known keys nested inside unknown field": `{"meta":{"name":"A","name":"B","datasets":[],"upstreams":null},` +
305				`"datasets":[{"name":"A","upstreams":[]}]}`,
306			"big numbers in unknown fields":          `{"note":1e400,"datasets":[{"name":"A","upstreams":[],"extra":[1e999,{"z":-1e400}]}]}`,
307			"case variant spellings declared once":   `{"Datasets":[{"Name":"A","Upstreams":[]},{"NAME":"B","UPSTREAMS":["A"]}]}`,
308			"duplicate names inside upstreams array": `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","A"]}]}`,
309		}
310		for name, data := range cases {
311			t.Run(name, func(t *testing.T) {
312				graph, err := UnmarshalGraphFile([]byte(data))
313				if err != nil {
314					t.Fatalf("UnmarshalGraphFile rejected a legal document: %v", err)
315				}
316				if name == "duplicate names inside upstreams array" {
317					if got := graph["B"].Parents; len(got) != 1 || got[0] != "A" {
318						t.Errorf("B.Parents = %v, want [A] (duplicates count once)", got)
319					}
320				}
321			})
322		}
323	
324		// Dataset names stay case-sensitive and keep their spaces; only field
325		// names fold.
326		graph, err := UnmarshalGraphFile([]byte(`{"datasets":[{"name":" A ","upstreams":[]},{"name":"a","upstreams":[" A "]}]}`))
327		if err != nil {
328			t.Fatalf("case/space-sensitive dataset names rejected: %v", err)
329		}
330		if got := graph["a"].Parents; len(got) != 1 || got[0] != " A " {
331			t.Errorf(`graph["a"].Parents = %v, want [" A "]`, got)
332		}
333	}
334

