73	// numbers in every kind of ignored position the reader must skip: a top-level
74	// unknown field before and after the known fields, unknown objects and arrays
75	// at the top level and inside the graph, and unknown fields of dataset
76	// records. The declared content id is deliberately bogus but non-empty; the
77	// name gate runs before the id comparison.
78	func snapshotBignumPlacements(contentID string, graphJSON string) map[string]string {
