274					if wantMsg == "" {
275						wantMsg = err.Error()
276					} else if err.Error() != wantMsg {
277						t.Errorf("error:\n%q\nwant:\n%q", err.Error(), wantMsg)
278					}
279				}
280			})
281		}
282	}
283	
284	// TestSnapshotGenuineNamesWithBigNumbersTraceSame pins the legal side: names
285	// that genuinely carry a replacement character (written directly or as the
286	// equivalent escape), correctly paired surrogate escapes, and text that
287	// merely looks like a Unicode escape (a real backslash followed by letters)
288	// all read verbatim, and with ignored big numbers present the trace still
289	// reports the same roots and paths. Direct writing and equivalent escaping
290	// produce identical results.
291	func TestSnapshotGenuineNamesWithBigNumbersTraceSame(t *testing.T) {
292		// Root 源� reached by a downstream named with a paired surrogate escape
293		// (😀); both the genuine U+FFFD direct spelling and its \u escape occur.
294		directGraph := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"ledger😀","upstreams":["源�"]}]}`
295		escapedGraph := `{"datasets":[{"name":"` + "\\u6e90\\ufffd" + `","upstreams":[]},` +
296			`{"name":"ledger` + "\\ud83d\\ude00" + `","upstreams":["` + "\\u6e90\\ufffd" + `"]}]}`
297		id := snapshotOf(t, directGraph).ContentID
298	
299		docs := map[string]string{
300			"plain direct": `{"formatVersion":1,"contentId":"` + id + `","graph":` + directGraph + `}`,
301			"equivalent escapes + big numbers": `{"note":1e400,"meta":[1e999,{"z":-1e400}],` +
302				`"formatVersion":1,"contentId":"` + id + `","graph":` + escapedGraph + `}`,
303			"big numbers in the graph and records": `{"formatVersion":1,"contentId":"` + id +
304				`","graph":{"note":1e400,"datasets":[{"vals":[1e999],"name":"源�","upstreams":[]},{"name":"ledger😀","upstreams":["源�"],"meta":-1e400}]},"tail":[2e400]}`,
305		}
306	
307		var wantDownstream, wantRoot string
308		for name, doc := range docs {
309			t.Run(name, func(t *testing.T) {
310				snap, err := ParseSnapshot([]byte(doc))
311				if err != nil {
312					t.Fatalf("legal snapshot rejected: %v", err)
313				}
314				if snap.ContentID != id {
315					t.Errorf("content id = %q, want %q; ignored fields must not change identity", snap.ContentID, id)
316				}
317				down, err := TraceSources(snap, "ledger😀")
318				if err != nil {
319					t.Fatalf("TraceSources ledger😀: %v", err)
320				}
321				gotDownstream := traceReportJSON(t, down)
322				root, err := TraceSources(snap, "源�")
323				if err != nil {
324					t.Fatalf("TraceSources 源�: %v", err)
325				}
326				gotRoot := traceReportJSON(t, root)
327				if wantDownstream == "" {
328					wantDownstream, wantRoot = gotDownstream, gotRoot
329				} else {
330					if gotDownstream != wantDownstream {
331						t.Errorf("downstream trace differs:\n%s\n%s", gotDownstream, wantDownstream)
332					}
333					if gotRoot != wantRoot {
334						t.Errorf("root self-trace differs:\n%s\n%s", gotRoot, wantRoot)
335					}
336				}
337				if !reflect.DeepEqual(down.Sources, []SourceTrace{{Root: "源�", Path: []string{"ledger😀", "源�"}}}) {
338					t.Errorf("downstream sources = %+v, want the genuine 源� root", down.Sources)
339				}
340				if !reflect.DeepEqual(root.Sources, []SourceTrace{{Root: "源�", Path: []string{"源�"}}}) {
341					t.Errorf("root sources = %+v, want itself as a single-element path", root.Sources)
342				}
343			})
344		}
345	
346		// A name that really contains a backslash and letters is plain text, not
347		// an escape: it stays its own dataset, queried directly and reached from a
348		// downstream, with ignored big numbers present.
349		lookalikeGraph := `{"datasets":[{"name":"x\\ud800","upstreams":[]},{"name":"y","upstreams":["x\\ud800"]}]}`
350		lookalikeID := snapshotOf(t, lookalikeGraph).ContentID
351		lookalikeDoc := `{"note":1e400,"formatVersion":1,"contentId":"` + lookalikeID +
352			`","graph":{"datasets":[{"vals":[1e999],"name":"x\\ud800","upstreams":[]},{"name":"y","upstreams":["x\\ud800"],"note":-1e400}]}}`
353		snap, err := ParseSnapshot([]byte(lookalikeDoc))
354		if err != nil {
355			t.Fatalf("backslash-lookalike snapshot rejected: %v", err)
356		}
357		report, err := TraceSources(snap, "y")
358		if err != nil {
359			t.Fatalf("TraceSources y: %v", err)
360		}
361		if !reflect.DeepEqual(report.Sources, []SourceTrace{{Root: `x\ud800`, Path: []string{"y", `x\ud800`}}}) {
362			t.Errorf("sources = %+v, want the verbatim backslash name", report.Sources)
363		}
364		self, err := TraceSources(snap, `x\ud800`)
365		if err != nil {
366			t.Fatalf("TraceSources x\\ud800: %v", err)
367		}
368		if !reflect.DeepEqual(self.Sources, []SourceTrace{{Root: `x\ud800`, Path: []string{`x\ud800`}}}) {
369			t.Errorf("self sources = %+v", self.Sources)
370		}
371	}
372	
373	// TestSnapshotUnknownBigNumbersDoNotChangeTraceReport: adding the ignored
374	// oversized-number content to one legal snapshot changes neither the content
375	// identifier nor the byte-for-byte trace report of any query, including a
376	// multi-branch graph where path tie-breaking matters.
377	func TestSnapshotUnknownBigNumbersDoNotChangeTraceReport(t *testing.T) {
378		graph := `{"datasets":[
379			{"name":"T","upstreams":["A","B"]},
380			{"name":"A","upstreams":["R"]},
381			{"name":"B","upstreams":["R"]},
382			{"name":"R","upstreams":[]},
383			{"name":"源�","upstreams":[]}
384		]}`
385		id := snapshotOf(t, graph).ContentID
386		variants := map[string]string{
387			"plain": `{"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
388			"big number at top": `{"note":1e400,` +
389				`"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
390			"big numbers nested everywhere": `{"meta":{"x":[1e400,{"y":1e999}]},` +
391				`"formatVersion":1,"contentId":"` + id + `","graph":{"note":[1e999,-1e400],` + graphJSONBody(graph) + `},"tail":2e400}`,
392			"big numbers inside every record": `{"formatVersion":1,"contentId":"` + id + `","graph":{"datasets":[
393				{"note":1e400,"name":"T","upstreams":["A","B"]},
394				{"vals":[1e999],"name":"A","upstreams":["R"]},
395				{"name":"B","upstreams":["R"],"meta":-1e400},
396				{"name":"R","upstreams":[],"deep":{"x":1e999}},
397				{"name":"源�","upstreams":[],"bag":[1e400]}
398			]}}`,
399		}
400	
401		queries := []string{"T", "R", "源�", "A"}
402		base := make(map[string]string, len(queries))
403		for variantName, doc := range variants {
404			snap, err := ParseSnapshot([]byte(doc))
405			if err != nil {
406				t.Fatalf("%s: ParseSnapshot: %v", variantName, err)
407			}
408			if snap.ContentID != id {
409				t.Errorf("%s: content id = %q, want %q", variantName, snap.ContentID, id)
410			}
411			for _, query := range queries {
412				report, err := TraceSources(snap, query)
413				if err != nil {
414					t.Fatalf("%s: trace %q: %v", variantName, query, err)
415				}
416				got := traceReportJSON(t, report)
417				if want, ok := base[query]; !ok {
418					base[query] = got
419				} else if got != want {
420					t.Errorf("%s: trace %q differs:\n%s\n%s", variantName, query, got, want)
421				}
422			}
423		}
424	}
425	
426	// graphJSONBody strips the one-level outer braces of a graph document so a
427	// variant can nest additional fields at the graph-object level.
428	func graphJSONBody(graph string) string {
429		return graph[1 : len(graph)-1]
430	}
431	
432	// traceReportJSON marshals a trace report deterministically for byte
433	// comparison (the report's slices are already ordered by the core).
434	func traceReportJSON(t *testing.T, report *TraceReport) string {
435		t.Helper()
436		b, err := json.Marshal(report)
437		if err != nil {
438			t.Fatalf("marshal trace report: %v", err)
439		}
440		return string(b)
441	}
