382				if _, err := ParseSnapshot([]byte(broken)); err == nil {
383					t.Fatalf("ParseSnapshot accepted malformed JSON %q", broken)
384				}
385			})
386		}
387	}
388	
389	// TestParseSnapshotDuplicateTolerances: repetitions that do NOT create
390	// ambiguity stay legal — unknown fields may repeat anywhere, each dataset
391	// record declares its own name, and duplicate names inside one upstreams
392	// array are still deduplicated (that is not a repeated field).
393	func TestParseSnapshotDuplicateTolerances(t *testing.T) {
394		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
395		id := snapshotOf(t, graph).ContentID
396		doc := func(body string) string {
397			return `{"formatVersion":1,"contentId":"` + id + `","graph":` + body + `}`
398		}
399	
400		cases := map[string]string{
401			"unknown top-level field repeats": `{"note":1,"note":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
402			"unknown graph field repeats":     doc(`{"meta":"x","meta":"y","datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
403			"unknown record field repeats":    doc(`{"datasets":[{"name":"A","note":"x","note":"y","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
404			"duplicate names inside upstreams array": doc(
405				`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","A"]}]}`),
406		}
407		for name, data := range cases {
408			t.Run(name, func(t *testing.T) {
409				parsed, err := ParseSnapshot([]byte(data))
410				if err != nil {
411					t.Fatalf("ParseSnapshot rejected a legal document: %v", err)
412				}
413				if parsed.ContentID != id {
414					t.Errorf("content id = %s, want %s", parsed.ContentID, id)
415				}
416			})
417		}
418	}
