420	// TestParseSnapshotCaseVariantSpellings: a field written once in any letter
421	// casing the reader already supports keeps working; only declaring it twice
422	// is an error.
423	func TestParseSnapshotCaseVariantSpellings(t *testing.T) {
424		id := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`).ContentID
425		data := `{"FORMATVERSION":1,"ContentID":"` + id + `","GRAPH":{"Datasets":` +
426			`[{"Name":"A","Upstreams":[]},{"NAME":"B","UPSTREAMS":["A"]}]}}`
427		parsed, err := ParseSnapshot([]byte(data))
428		if err != nil {
429			t.Fatalf("case-variant spellings rejected: %v", err)
430		}
431		if parsed.ContentID != id {
432			t.Errorf("content id = %s, want %s", parsed.ContentID, id)
433		}
434	}
