436	// TestParseSnapshotRejectsUnicodeFoldDuplicates: two keys that the JSON
437	// reader resolves to the same struct field through Unicode simple case
438	// folding — not merely ASCII case — make the snapshot ambiguous. U+017F
439	// LATIN SMALL LETTER LONG S ("ſ") is a fold equivalent of "s", so
440	// "formatVerſion" and "formatVersion" select the same field, as do
441	// "dataſets"/"datasets" and "upſtreams"/"upstreams". Writing the rune
442	// directly or via a JSON escape must not matter, and identical values, a null
443	// first value, or reversed declaration order must not save the document. The
444	// error names the canonical field and, inside a datasets record, its index.
445	func TestParseSnapshotRejectsUnicodeFoldDuplicates(t *testing.T) {
446		const (
447			longS = "ſ" // U+017F LATIN SMALL LETTER LONG S, folds to ASCII "s"
448			// longSEscape is the JSON escape spelling of the same rune as literal
449			// document bytes (backslash, u, 0, 1, 7, f).
450			longSEscape = "\\" + "u017f"
451		)
452		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
453		id := snapshotOf(t, graph).ContentID
454		doc := func(body string) string {
455			return `{"formatVersion":1,"contentId":"` + id + `","graph":` + body + `}`
456		}
457	
458		cases := map[string]struct {
459			data  string
460			field string
461		}{
462			"long s version 2 then 1": {
463				`{"formatVer` + longS + `ion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
464				"formatVersion",
465			},
466			"long s version reversed order": {
467				`{"formatVersion":1,"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
468				"formatVersion",
469			},
470			"long s version identical values": {
471				`{"formatVer` + longS + `ion":1,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
472				"formatVersion",
473			},
474			"long s version via JSON escape": {
475				`{"formatVer` + longSEscape + `ion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
476				"formatVersion",
477			},
478			"null long s version then valid": {
479				`{"formatVer` + longS + `ion":null,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
480				"formatVersion",
481			},
482			"datasets versus long s datasets": {
483				doc(`{"data` + longS + `ets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
484				"datasets",
485			},
486			"long s datasets via JSON escape": {
487				doc(`{"data` + longSEscape + `ets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
488				"datasets",
489			},
490			"upstreams versus long s upstreams": {
491				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":["A"],"upstreams":["A"]}]}`),
492				"upstreams",
493			},
494			"long s upstreams via JSON escape": {
495				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longSEscape + `treams":["A"],"upstreams":["A"]}]}`),
496				"upstreams",
497			},
498			"null long s upstreams then valid": {
499				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":null,"upstreams":["A"]}]}`),
500				"upstreams",
501			},
502		}
503		for name, tc := range cases {
504			t.Run(name, func(t *testing.T) {
505				// Every "escape" case really must carry ASCII escape bytes.
506				if strings.Contains(name, "escape") && !strings.Contains(tc.data, longSEscape) {
507					t.Fatalf("test case %q does not actually use a JSON escape", name)
508				}
509				_, err := ParseSnapshot([]byte(tc.data))
510				if !errors.Is(err, ErrInvalidArgument) {
511					t.Fatalf("err = %v, want ErrInvalidArgument", err)
512				}
513				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
514					t.Errorf("err = %q, want it to name canonical field %q", err, tc.field)
515				}
516			})
517		}
518	
519		// The duplicate lives in the second dataset record; the error must locate
520		// that record by its datasets array index even for a Unicode-fold key.
521		indexed := doc(`{"datasets":[{"name":"A","upstreams":[]},{"up` + longS + `treams":["A"],"name":"B","upstreams":["A"]}]}`)
522		if _, err := ParseSnapshot([]byte(indexed)); err == nil || !strings.Contains(err.Error(), "index 1") {
523			t.Errorf("err = %v, want the datasets index of the offending record", err)
524		}
525	
526		// A top-level long-s spelling twice also collides at the top level.
527		twice := `{"formatVer` + longS + `ion":1,"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`
528		if _, err := ParseSnapshot([]byte(twice)); err == nil ||
529			!strings.Contains(err.Error(), `"formatVersion"`) ||
530			!strings.Contains(err.Error(), "top level") {
531			t.Errorf("err = %v, want a top-level formatVersion duplicate error", err)
532		}
533	}
534	
535	// TestParseSnapshotUnicodeFoldSpellingDeclaredOnce preserves read
536	// compatibility: a known field written exactly once in a Unicode-fold
537	// spelling is still recognized, and a key with the same name nested inside an
538	// unknown field is independent of the outer object's known-field check.
539	func TestParseSnapshotUnicodeFoldSpellingDeclaredOnce(t *testing.T) {
540		const (
541			longS       = "ſ"
542			longSEscape = "\\" + "u017f"
543		)
544		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
545		id := snapshotOf(t, graph).ContentID
546	
547		cases := map[string]string{
548			"long s version declared once": `{"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
549			"long s datasets declared once": `{"formatVersion":1,"contentId":"` + id +
550				`","graph":{"data` + longS + `ets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}}`,
551			"long s upstreams declared once": `{"formatVersion":1,"contentId":"` + id +
552				`","graph":{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":["A"]}]}}`,
553			"escaped long s version declared once": `{"formatVer` + longSEscape + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
554			"same key nested inside unknown field": `{"formatVersion":1,"contentId":"` + id + `","graph":` + graph +
555				`,"meta":{"formatVersion":2,"datasets":null}}`,
556			"fold-spelled key nested inside unknown field": `{"formatVersion":1,"contentId":"` + id + `","graph":` +
557				graph + `,"meta":{"formatVer` + longS + `ion":2,"data` + longS + `ets":[]}}`,
558		}
559		for name, data := range cases {
560			t.Run(name, func(t *testing.T) {
561				parsed, err := ParseSnapshot([]byte(data))
562				if err != nil {
563					t.Fatalf("a field declared once in a fold spelling was rejected: %v", err)
564				}
565				if parsed.ContentID != id {
566					t.Errorf("content id = %s, want %s", parsed.ContentID, id)
567				}
568			})
569		}
570	}
571	
572	// A is a root source of B, C depends on B; repointing B at another root X must
573	// report BOTH B and C changing source from A to X.
574	func TestCompareHeadlineRootSourceChange(t *testing.T) {
575		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
576		newSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"X","upstreams":[]},{"name":"B","upstreams":["X"]},{"name":"C","upstreams":["B"]}]}`)
577	
578		report := CompareSnapshots(oldSnap, newSnap)
579		if got, want := report.NewDatasets, []string{"X"}; !reflect.DeepEqual(got, want) {
580			t.Errorf("NewDatasets = %v, want %v", got, want)
581		}
582		if len(report.RemovedDatasets) != 0 {
583			t.Errorf("RemovedDatasets = %v, want empty", report.RemovedDatasets)
584		}
585		if got, want := report.ChangedDatasets, []string{"B"}; !reflect.DeepEqual(got, want) {
586			t.Errorf("ChangedDatasets = %v, want %v", got, want)
587		}
588		wantAdded := []Relation{{Upstream: "X", Downstream: "B"}}
589		wantRemoved := []Relation{{Upstream: "A", Downstream: "B"}}
590		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
591			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
592		}
593		if !reflect.DeepEqual(report.RemovedRelations, wantRemoved) {
594			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
595		}
596		wantRootChanges := []RootSourceChange{
597			{Dataset: "B", OldRoots: []string{"A"}, NewRoots: []string{"X"}},
598			{Dataset: "C", OldRoots: []string{"A"}, NewRoots: []string{"X"}},
599		}
600		if !reflect.DeepEqual(report.RootSourceChanges, wantRootChanges) {
601			t.Errorf("RootSourceChanges = %v\nwant %v", report.RootSourceChanges, wantRootChanges)
602		}
603	}
604	
605	// TestCompareNodeDeletionCascadesRelations verifies that removing a node lists
606	// every edge incident to it among the removed relations.
607	func TestCompareNodeDeletionCascadesRelations(t *testing.T) {
608		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
609		// B is deleted; C now derives directly from A.
610		newSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"C","upstreams":["A"]}]}`)
611	
612		report := CompareSnapshots(oldSnap, newSnap)
613		if got, want := report.RemovedDatasets, []string{"B"}; !reflect.DeepEqual(got, want) {
614			t.Errorf("RemovedDatasets = %v, want %v", got, want)
615		}
616		if got, want := report.ChangedDatasets, []string{"C"}; !reflect.DeepEqual(got, want) {
617			t.Errorf("ChangedDatasets = %v, want %v", got, want)
618		}
619		wantRemoved := []Relation{
620			{Upstream: "A", Downstream: "B"},
621			{Upstream: "B", Downstream: "C"},
622		}
623		if !reflect.DeepEqual(report.RemovedRelations, wantRemoved) {
624			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
625		}
626		wantAdded := []Relation{{Upstream: "A", Downstream: "C"}}
627		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
628			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
629		}
630		// A and C are common and both still root at A; B was removed and must not
631		// appear in the root-source list.
632		if len(report.RootSourceChanges) != 0 {
633			t.Errorf("RootSourceChanges = %v, want empty", report.RootSourceChanges)
634		}
635	}
