637	// TestCompareSameRootsDifferentPath verifies that adjusting the path while
638	// still reaching the same root set is not reported as a source change.
639	func TestCompareSameRootsDifferentPath(t *testing.T) {
640		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
641		newSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B","A"]}]}`)
