652	// TestCompareNodeBecomingRoot: a node's own source includes itself, so when B
653	// stops depending on A and becomes a root, its source set changes A -> B.
654	func TestCompareNodeBecomingRoot(t *testing.T) {
655		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
656		newSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":[]}]}`)
