664	func TestCompareRootsMultipathOnceAndSorted(t *testing.T) {
665		// C reaches A and B (both roots) by two paths; duplicates count once and
666		// the set is name-sorted.
667		adj := adjacency{
668			"A": nil,
669			"B": nil,
670			"C": {"A", "B"},
671			"D": {"C", "A"},
672		}
673		got := rootSources("D", adj)
674		want := []string{"A", "B"}
675		if !reflect.DeepEqual(got, want) {
