683	func TestCompareSelfAndEmpty(t *testing.T) {
684		t.Run("identical snapshot all diffs empty", func(t *testing.T) {
685			snap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
